-- 073k: reports. Bids: count, value, submitted and won amounts, win rate (won out of won plus lost) and average score,
-- by status, source, result, owner, organization or month. Same catalog as 069g plus bids.
create or replace function private.report_catalog() returns jsonb language sql immutable set search_path = pg_catalog as $$
  select '{
    "contacts": {"table": "people", "date": "created_at", "owner": null,
      "groups": {"lead_source": "coalesce(lead_source, ''(none)'')", "preferred_contact_method": "coalesce(preferred_contact_method, ''(none)'')", "tag": "unnest(case when cardinality(tags) = 0 then array[''(no tags)''] else tags end)"},
      "measures": {"count": "count(*)"}},
    "organizations": {"table": "companies", "date": "created_at", "owner": "owner_id",
      "groups": {"stage": "coalesce(stage, ''(none)'')", "owner": "coalesce((select full_name from app_users where id = owner_id), ''(nobody)'')", "lead_source": "coalesce(lead_source_channel, ''(none)'')",
                 "city": "coalesce(city, ''(none)'')", "state": "coalesce(state, ''(none)'')", "interest_level": "coalesce(interest_level, ''(none)'')", "tag": "unnest(case when cardinality(tags) = 0 then array[''(no tags)''] else tags end)"},
      "measures": {"count": "count(*)"}},
    "deals": {"table": "opportunities", "date": "created_at", "owner": "owner_id",
      "groups": {"status": "coalesce(status, ''(none)'')", "owner": "coalesce((select full_name from app_users where id = owner_id), ''(nobody)'')", "service": "coalesce(service, ''(none)'')",
                 "lead_source": "coalesce(lead_source, (select lead_source_channel from companies where id = company_id), ''(none)'')"},
      "measures": {"count": "count(*)", "value": "coalesce(sum(estimated_value), 0)", "average_value": "round(coalesce(avg(estimated_value), 0), 2)"}},
    "chats": {"table": "chat_threads", "date": "created_at", "owner": "assigned_to", "where": "kind is distinct from ''team''",
      "groups": {"person": "coalesce((select full_name from app_users where id = assigned_to), ''(nobody)'')", "widget": "coalesce((select name from chat_widgets where id = widget_id), ''(default)'')", "source": "coalesce(source, ''(none)'')", "status": "coalesce(status, ''(none)'')"},
      "measures": {"count": "count(*)", "picked_up": "count(picked_up_at)", "missed": "count(*) filter (where picked_up_at is null)", "avg_pickup_minutes": "round(coalesce(avg(extract(epoch from picked_up_at - created_at) / 60.0), 0)::numeric, 1)"}},
    "todos": {"table": "tasks", "date": "created_at", "owner": "assigned_to",
      "groups": {"person": "coalesce((select full_name from app_users where id = assigned_to), ''(nobody)'')", "done": "case when done then ''Done'' else ''Open'' end"},
      "measures": {"count": "count(*)", "done": "count(*) filter (where done)", "overdue": "count(*) filter (where not done and due_date < current_date)"}},
    "jobs": {"table": "jobs", "date": "created_at", "owner": "assigned_to", "where": "archived_at is null",
      "groups": {"person": "coalesce((select full_name from app_users where id = assigned_to), ''(nobody)'')", "status": "status", "service_type": "coalesce(service_type, ''(none)'')"},
      "measures": {"count": "count(*)", "revenue": "coalesce(sum(price), 0)", "completed": "count(*) filter (where status in (''completed'', ''left''))"}},
    "proposals": {"table": "proposals", "date": "accepted_at", "owner": "owner_id", "where": "status = ''accepted''",
      "groups": {"lead_source": "coalesce(lead_source, (select lead_source_channel from companies where id = company_id), ''(none)'')", "owner": "coalesce((select full_name from app_users where id = owner_id), ''(nobody)'')"},
      "measures": {"count": "count(*)", "due_at_signing": "coalesce(sum((select setup_total from proposal_versions v where v.proposal_id = proposals.id and v.version = proposals.accepted_version)), 0)",
                   "monthly": "coalesce(sum((select monthly_total from proposal_versions v where v.proposal_id = proposals.id and v.version = proposals.accepted_version)), 0)"}},
    "invoices": {"table": "invoices", "date": "issue_date", "owner": "owner_id", "where": "status not in (''void'', ''draft'')",
      "groups": {"lead_source": "coalesce(lead_source, ''(none)'')", "status": "status", "owner": "coalesce((select full_name from app_users where id = owner_id), ''(nobody)'')",
                 "organization": "coalesce((select name from companies where id = company_id), ''(none)'')"},
      "measures": {"revenue": "coalesce(sum(paid_total + deposit), 0)", "billed": "coalesce(sum(total), 0)", "balance_due": "coalesce(sum(balance), 0)", "count": "count(*)",
                   "paid": "count(*) filter (where status = ''paid'')", "average": "round(coalesce(avg(total), 0), 2)"}},
    "bids": {"table": "bids", "date": "created_at", "owner": "owner_id", "where": "archived_at is null",
      "groups": {"status": "status", "source": "source", "result": "coalesce(override_result, result, ''(not scored)'')", "owner": "coalesce((select full_name from app_users where id = owner_id), ''(nobody)'')",
                 "organization": "coalesce((select name from companies where id = company_id), client_name, ''(none)'')"},
      "measures": {"count": "count(*)", "value": "coalesce(sum(est_value), 0)", "submitted": "coalesce(sum(submitted_amount), 0)", "won": "count(*) filter (where status = ''won'')",
                   "won_value": "coalesce(sum(submitted_amount) filter (where status = ''won''), 0)", "lost": "count(*) filter (where status = ''lost'')",
                   "win_rate": "coalesce(round(100.0 * count(*) filter (where status = ''won'') / nullif(count(*) filter (where status in (''won'', ''lost'')), 0), 1), 0)",
                   "average_score": "round(coalesce(avg(score), 0), 1)"}},
    "activity": {"table": "contact_events", "date": "created_at", "owner": "actor",
      "groups": {"kind": "kind", "person": "coalesce((select full_name from app_users where id = actor), ''(automatic)'')"},
      "measures": {"count": "count(*)"}}
  }'::jsonb
$$;
